#!/usr/bin/env python3
"""Persist completed L22 revision review, without modifying authored content."""
import json,hashlib,datetime,sys
from pathlib import Path
R=Path(__file__).resolve().parents[1];sys.path.insert(0,str(R/'scripts'))
from validate import question_hash,schema_errors,CHECK_KEYS
AUTHOR='build_offline_study_interface:L22-independent-reviewer'
batchpath=R/'data/question-batches/W05-L22.json';raw=batchpath.read_bytes();batch=json.loads(raw);qs={q['id']:q for q in batch['questions']}
p=R/'audits/W05-L22-quality-repairs-independent-answers.json';frozen=json.loads(p.read_text());assert frozen['currentRevisedKeysRead'] is False
assert hashlib.sha256(p.read_bytes()).hexdigest()=='bfd80d49896bbfc1ba206c4c19e80d61aad2c7d8bc720007d8033a1531635494'
old=json.loads((R/'data/reviews/W05-L22-v1-independent-interface.json').read_text())['reviews'];preserved={r['questionId']:r['questionSha256'] for r in old if r['decision']=='verified'}
assert len(preserved)==36 and all(question_hash(qs[k])==v for k,v in preserved.items())
flags={
6:{'explanation':'Restore normal spacing in option o4: “direction45°” should read “direction 45°”. The repaired cross-product scenario and answer are correct.'},
7:{'explanation':'The SI constants and both answers are now consistent, but all options and repeated solution fields contain merged prose/quantities: “and25 V”, “and4 V”, “are0.4”, “are12 W”, “torque0.4”, “EMF0.4”, and “Check1.2”. Insert ordinary word/quantity spacing throughout, including simpleExplanation and steps.'},
14:{'explanation':'The corrected derivation and distractor rationale are sound. Restore the missing space in the final step “Multiply byη” to “Multiply by η”.'},
19:{'explanation':'The bandwidth-separation alternatives are now meaningful, but normalize prose/quantity spacing in stem and options, including “of10 rad/s”, “over0–10”, “at8”, “is1000” and “near10”.'},
25:{'sourceSupport':'The only citation is p681, which supplies the shaft-resonance model/value. Add p679 and/or p680 as inspected evidence for the half-resonance design rule and normalized critical-gain relations; the revised question requires those additional source claims.','explanation':'Restore spacing throughout the stem, options and repeated solution fields: examples include “is20”, “approximately3.183”, “about1.592”, “halving3.183”, “Treat20”, “the20rad/s”, “half of20rad/s is10rad/s” and “value10”. Separate prose, values and units consistently. The rad/s-versus-Hz arithmetic and key are correct.'},
26:{'explanation':'The diagram matches and model-specific qualifications are correct. Restore prose/quantity spacing, including “page682”, “mass0.23m”, “inertia0.33I” and “use0.23m”, in stem, options and both explanation copies.'},
34:{'explanation':'The state-vector/derivative pairs now correctly assess order. Insert spaces before the vectors in options, such as “state is [ω]”, “derivative [ω̇]” and “uses [θ,ω]”, rather than merged prose/brackets.'},
43:{'explanation':'The physical torque-accounting repair is correct. Restore quantity spacing in the options: “no-load20rad/s”, “the2N·m” and “All2N·m” should be ordinary spaced prose and SI quantities.'},
59:{'sourceSupport':'The cutaway and PID block support the named components and feedback role, but neither cited page states the speed/transmitted-torque gear relation used in the key. Add inspected p676 for that mechanical-transmission claim. Do not remove the valid no-load/friction qualification elsewhere.'},
60:{'explanation':'The explicit state counts 2, 3 and 5 are correct. Restore spacing in “state[θ,ω]” and every “then3”, “then4”, “then5” option phrase so the new learning item uses readable prose.'}
}
now=datetime.datetime.now(datetime.timezone.utc).isoformat();reviews=[]
for a in frozen['answers']:
 q=qs[a['questionId']];assert q['version']==a['questionVersion'];assert set(q['correctOptionIds'])==set(a['independentAnswerOptionIds']);n=int(q['id'].split('-Q')[1]);f=flags.get(n,{})
 reasoning=a['reasoning']+' Current source-based reasoning was frozen before opening the revised keyed batch; the reviewer previously reviewed v1, so this is explicitly not represented as a fresh blind review. All current answer sets agree. All nine dimensions were checked against the actual cited page pixels, full options, per-option rationales, steps, formula definitions, assumptions and nearby questions. Independent algebra has 17 named passing checks and 1,000 randomized gear-reflection cases, not the author check suite. '+('The listed source-binding/readability defects block approval of this version; there is no answer correction.' if f else 'All nine dimensions pass within the stated scope; source disagreements and conditional model assumptions remain preserved.')
 reviews.append({'id':f'REV-{q["id"]}-v{q["version"]}-quality-repairs-interface','questionId':q['id'],'questionVersion':q['version'],'questionSha256':question_hash(q),'reviewerId':AUTHOR,'decision':'flagged' if f else 'verified','reviewedAt':now,'sourceVersions':{c['sourceId']:c['sourceSha256'] for c in q['citations']},'reviewedSlideIds':list(dict.fromkeys(c['slideId'] for c in q['citations'])),'independentAnswerOptionIds':a['independentAnswerOptionIds'],'solvedBeforeAnswerSeen':False,'reviewKind':'independent revision re-review with prior v1 exposure; new gap answers also frozen before current-key access','checks':{k:k not in f for k in CHECK_KEYS},'reasoning':reasoning,'findings':[f'{k}: {v}' for k,v in f.items()]})
schema=json.loads((R/'data/schema.review.json').read_text());errors=[e for r in reviews for e in schema_errors(r,schema)];assert not errors,errors
out=R/'data/reviews/W05-L22-quality-repairs-independent-interface.json';out.write_text(json.dumps({'reviewerId':AUTHOR,'reviews':reviews},ensure_ascii=False,indent=2)+'\n')
report={'reviewerId':AUTHOR,'completedAt':now,'reviewKind':'revision re-review with prior v1 exposure disclosed','questionCount':len(reviews),'verified':sum(r['decision']=='verified' for r in reviews),'flagged':sum(r['decision']=='flagged' for r in reviews),'keyDisagreements':0,'revisitedActualPages':frozen['revisitedActualPages'],'originalFullCoveragePages':list(range(669,695)),'preservedAcceptedHashes':preserved,'sourceFirstAnswerPath':str(p.relative_to(R)),'sourceFirstAnswerSha256':hashlib.sha256(p.read_bytes()).hexdigest(),'reviewFile':str(out.relative_to(R)),'reviewSha256':hashlib.sha256(out.read_bytes()).hexdigest(),'authorBatchSha256':hashlib.sha256(raw).hexdigest(),'independentComputationPath':'audits/W05-L22-quality-repairs-independent-computations.json','findings':[{'questionId':f'W05-L22-Q{n:03d}','criteria':list(f),'findings':list(f.values())} for n,f in flags.items()],'coverageChallenge':[{'id':'L22-COVERAGE-01','status':'substantively addressed; citation repair pending','questionId':'W05-L22-Q059','note':'Meaningful cutaway component-role match exists; add p676 gear-law support.'},{'id':'L22-COVERAGE-02','status':'substantively addressed; readability repair pending','questionId':'W05-L22-Q026','note':'Actual lateral 0.23m and torsional 0.33I diagrams are now distinguished.'},{'id':'L22-COVERAGE-03','status':'substantively addressed; readability repair pending','questionId':'W05-L22-Q060','note':'Explicit electrical/flexible retained-state counts now tested. No further substantive gap found within the previously inspected 26-page boundary.'}],'sourceQualifications':'All original source disputes remain local and qualified; no PDF or source globally resolved.','mutations':'Review scripts, computation report, reviews and audit only. Authored batch, source, canonical bank and Git unchanged.'}
(R/'audits/W05-L22-quality-repairs-independent-summary.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
assert batchpath.read_bytes()==raw
print(json.dumps({k:report[k] for k in ['questionCount','verified','flagged','keyDisagreements']}))
